import { execFileSync } from "node:child_process"
import { writeFileSync } from "node:fs"
import { dirname, resolve } from "node:path"
import { fileURLToPath } from "node:url"

const __dirname = dirname(fileURLToPath(import.meta.url))
const outputPath = resolve(__dirname, "../src/types/database.generated.ts")
const projectId = "jvzgmhvwirsbdkjpmvla"

const banner = `/**
 * AUTO-GENERATED FILE.
 * Source: \`supabase gen types typescript --project-id ${projectId}\`
 * Do not edit this file manually.
 */

`

const generated = execFileSync(
  "supabase",
  ["gen", "types", "typescript", "--project-id", projectId],
  {
    cwd: resolve(__dirname, ".."),
    encoding: "utf8",
    stdio: ["ignore", "pipe", "inherit"],
  },
)

writeFileSync(outputPath, `${banner}${generated.trimStart()}\n`, "utf8")
